// Times Duel with Battle Music: Hungarian Dance No. 5
import React, { useState, useEffect, useRef } from 'react';
import confetti from 'canvas-confetti';

const getRandomQuestion = () => {
  const a = Math.floor(Math.random() * 12) + 1;
  const b = Math.floor(Math.random() * 12) + 1;
  return { a, b, answer: a * b };
};



export default function TimesDuel() {
  const [playerWins, setPlayerWins] = useState(0);
  const [cpuWins, setCpuWins] = useState(0);
  const [playerTime, setPlayerTime] = useState(30);
  const [opponentTime, setOpponentTime] = useState(30);
  const [question, setQuestion] = useState(getRandomQuestion());
  const [input, setInput] = useState('');
  const [status, setStatus] = useState('');
  const [cpuMode] = useState(true);
  const [gameActive, setGameActive] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [countdown, setCountdown] = useState(null);
  const [totalGameTime, setTotalGameTime] = useState(0);
  const [streak, setStreak] = useState(0);
  const [feedback, setFeedback] = useState(null);
  const musicRef = useRef(null);
  const gameContainerRef = useRef(null);
  const inputRef = useRef(null);



  const startGame = () => {
    setGameActive(true);
    setCountdown(3);
    setHasStarted(false);
    setStatus('counting');
    setPlayerTime(30);
    setOpponentTime(30);
    setTotalGameTime(0);
    setInput('');
    setQuestion(getRandomQuestion());
    setStreak(0);
    setFeedback(null);
  
    // Delay the play to avoid browser restrictions
    setTimeout(() => {
      if (musicRef.current) {
        musicRef.current.currentTime = 0;
        musicRef.current.play().catch(err => {
          console.log('Playback blocked:', err);
        });
      }
    }, 100); // Small delay to allow rendering and user gesture to register
  };
  

  useEffect(() => {
    if (countdown === 0) {
      setHasStarted(true);
      setStatus('Playing...');
      if (musicRef.current) {
        musicRef.current.currentTime = 0;
        musicRef.current.play();
      }
      return;
    }
    const timer = setTimeout(() => setCountdown(c => c - 1), 1000);
    return () => clearTimeout(timer);
  }, [countdown]);

  useEffect(() => {
    if (!hasStarted || status !== 'Playing...') return;
    const interval = setInterval(() => {
      setPlayerTime(t => Math.max(0, t - 1));
      setOpponentTime(t => Math.max(0, t - 1));
      setTotalGameTime(t => t + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, [hasStarted, status]);

  useEffect(() => {
    if (!hasStarted || status !== 'Playing...') return;
    if (playerTime <= 0) {
      setStatus('You Lost!');
      setCpuWins(w => w + 1);
    } else if (opponentTime <= 0) {
      setStatus('You Won!');
      setPlayerWins(w => w + 1);
      confetti({ particleCount: 150, spread: 100, origin: { y: 0.6 } });
    } else if (totalGameTime >= 180) {
      if (playerTime > opponentTime) {
        setStatus('You Won!');
        setPlayerWins(w => w + 1);
        confetti({ particleCount: 150, spread: 100, origin: { y: 0.6 } });
      } else if (playerTime < opponentTime) {
        setStatus('You Lost!');
        setCpuWins(w => w + 1);
      } else {
        setStatus("It's a Tie!");
      }
    }
  }, [playerTime, opponentTime, totalGameTime, hasStarted, status]);

  useEffect(() => {
    if (!cpuMode || status !== 'Playing...') return;
    const cpuInterval = setInterval(() => {
      if (status !== 'Playing...') return;
      if (Math.random() < 0.85) {
        setOpponentTime(t => Math.min(60, t + 2));
        setPlayerTime(t => Math.max(0, t - 2));
      }
    }, 1600);
    return () => clearInterval(cpuInterval);
  }, [cpuMode, status]);

  useEffect(() => {
    if (status !== 'Playing...' && musicRef.current) {
      musicRef.current.pause();
    }
  }, [status]);

  useEffect(() => {
    if (hasStarted && status === 'Playing...' && inputRef.current) {
      inputRef.current.focus({ preventScroll: true });
    }
  }, [hasStarted, status]);
  
  useEffect(() => {
    if (hasStarted && gameContainerRef.current) {
      gameContainerRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [hasStarted]);
  

  const handleSubmit = () => {
    if (!input.trim() || status !== 'Playing...') return;
    const isCorrect = parseInt(input) === question.answer;
    if (isCorrect) {
      setPlayerTime(t => t + 2);
      setOpponentTime(t => Math.max(0, t - 2));
      setStreak(s => s + 1);
      setFeedback('✅');
    } else {
      setStreak(0);
      setFeedback('❌');
    }
    setTimeout(() => setFeedback(null), 500);
    setQuestion(getRandomQuestion());
    setInput('');
  
    // 🧠 Re-focus to keep keyboard open
    if (inputRef.current) {
      inputRef.current.focus();
    }
  };
  

  const handleKeyDown = e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSubmit();
    }
  };

  const resetTally = () => {
    setPlayerWins(0);
    setCpuWins(0);
  };

  const total = playerTime + opponentTime || 1;
  const playerPercent = (playerTime / total) * 100;
  const opponentPercent = 100 - playerPercent;

  return (
    <div ref={gameContainerRef} className="flex flex-col items-center justify-center min-h-screen gap-6 px-4 py-6 bg-gradient-to-br from-amber-100 via-pink-100 to-sky-200 font-sans overflow-hidden">
  
      <audio ref={musicRef} src={`${process.env.PUBLIC_URL}/hungarian_dance_no5.mp3`} loop preload="auto" />
  
      <h1 className="text-5xl sm:text-6xl font-extrabold tracking-wide text-indigo-700 drop-shadow-xl text-center">× Duel</h1>
  
      <div className="flex flex-wrap gap-4 text-lg sm:text-xl font-medium text-gray-800 items-center justify-center">
        <span className="flex items-center gap-2">🏆 You: <span className="text-green-700 font-bold">{playerWins}</span></span>
        <span className="flex items-center gap-2">🤖 CPU: <span className="text-red-700 font-bold">{cpuWins}</span></span>
        <button onClick={resetTally} className="btn-reset">
          Reset
        </button>
      </div>
  
      {!gameActive && (
        <button onClick={startGame} className="btn-green-gradient px-8 py-4 rounded-full text-xl shadow-md hover:scale-105 transition">
          Start Game
        </button>
      )}
  
      {gameActive && !hasStarted && countdown !== null && (
        <div className="text-7xl sm:text-8xl font-black text-gray-900 animate-bounce drop-shadow-lg">
          {countdown === 0 ? 'Go!' : countdown}
        </div>
      )}
  
      {hasStarted && (
        <>
          <button
            onClick={() => window.location.reload()}
            className="btn-home mt-2 sm:mt-0"
          >
            ⬅️ Back to Home
          </button>
  
          <div className="w-full max-w-xl">
            <div className="flex justify-between text-base sm:text-lg font-semibold text-gray-700">
              <span className="text-green-700">Your Time: {playerTime}s</span>
              <span className="text-red-700">Opponent Time: {opponentTime}s</span>
            </div>
            <div className="relative w-full h-12 bg-white border rounded-full my-4 overflow-hidden shadow-inner">
              <div className="progress-green h-full absolute left-0 top-0" style={{ width: `${playerPercent}%` }} />
              <div className="progress-red h-full absolute right-0 top-0" style={{ width: `${opponentPercent}%` }} />
            </div>
          </div>
  
          <div className="text-2xl sm:text-3xl font-semibold text-gray-900 text-center">
            What is <span className="text-blue-700 font-bold">{question.a}</span> × <span className="text-blue-700 font-bold">{question.b}</span>?
          </div>
  
          <div className="flex flex-col sm:flex-row gap-4 items-center mt-4 w-full max-w-xl">
            <input
              ref={inputRef}
              type="number"
              className="w-full sm:w-auto flex-1 border-2 border-gray-400 p-3 rounded-lg text-lg shadow focus:outline-none focus:ring-2 focus:ring-blue-400"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
            />
            <button
              onClick={handleSubmit}
              className="btn-submit w-full sm:w-auto"
              disabled={!input.trim() || status !== 'Playing...'}
            >
              Submit
            </button>
          </div>
  
          <div className="mt-3 text-xl sm:text-2xl font-semibold text-gray-800 italic text-center">{status}</div>
  
          {feedback && (
            <div className="text-5xl sm:text-6xl animate-bounce mt-2">{feedback}</div>
          )}
  
          {streak >= 3 && (
            <div className="text-lg text-green-600 mt-1 font-semibold">
              🔥 Streak: {streak}!
            </div>
          )}
  
          {(status === 'You Won!' || status === 'You Lost!' || status === "It's a Tie!") && (
            <div className={`fixed inset-0 flex flex-col items-center justify-center text-white z-50 px-4 text-center transition-all duration-500 ${
              status === 'You Won!' ? 'bg-green-600' :
              status === 'You Lost!' ? 'bg-red-600' : 'bg-yellow-500'
            }`}>
              <h2 className="text-4xl sm:text-5xl font-bold mb-6 drop-shadow-lg">{status}</h2>
              <button
                onClick={startGame}
                className="bg-white text-gray-800 px-8 py-3 rounded-full font-semibold text-lg shadow hover:bg-gray-100 transition"
              >
                🔁 Play Again
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
  }
  